}) }}

parameters.jsCode:
// Keep found places and turn nested fields into readable cells for Google Sheets.
const days = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
return $input.all()
  .filter((item) => item.json.found !== false)
  .map(({ json: p }) => ({
    json: {
      name: p.name,
      category: p.category,
      address: p.address,
      city: p.city,
      postalCode: p.postalCode,
      phone: p.phone,
      website: p.website,
      rating: p.rating,
      reviewsCount: p.reviewsCount,
      isClaimed: p.isClaimed,
      openingHours: p.openingHours
        ? days.map((d) => `${d.slice(0, 3)} ${(p.openingHours[d] || []).join(', ') || 'closed'}`).join(' | ')
        : null,
      latitude: p.latitude,
      longitude: p.longitude,
      googleMapsUrl: p.googleMapsUrl,
      searchQuery: p.searchQuery,
      scrapedAt: p.observedAt,
    },
  }));
